   "passage": "Durante l'estate il comune attiva un piano di prevenzione degli effetti del caldo rivolto alle persone con più di 75 anni che vivono sole. Il piano si basa su un bollettino giornaliero con tre livelli di rischio, elaborato dal servizio meteorologico regionale. Quando viene dichiarato il livello più alto, i volontari della protezione civile telefonano a tutte le persone iscritte nell'elenco comunale e, se necessario, organizzano una visita a domicilio. L'iscrizione all'elenco è gratuita e avviene su richiesta dell'interessato o di un familiare; il medico di famiglia può segnalare i propri assistiti solo con il loro consenso. La scorsa estate gli iscritti erano 2.300, su circa 9.000 residenti nella fascia di età interessata. Nei giorni di allerta il comune apre inoltre cinque centri climatizzati, dalle 11 alle 18. Per il prossimo anno è allo studio un accordo con le farmacie per distribuire materiale informativo.",
