   "passage": "Poiché la Terra compie una rotazione completa in 24 ore, la sua superficie è divisa convenzionalmente in 24 fusi orari, ciascuno ampio in teoria 15 gradi di longitudine. Procedendo verso est l'ora locale è sempre più avanzata, e questo obbliga a fissare un punto in cui cambia la data: è la linea internazionale del cambiamento di data, che segue in gran parte il meridiano di 180 gradi, nell'oceano Pacifico. Chi la attraversa viaggiando verso ovest deve aggiungere un giorno alla data, mentre chi la attraversa verso est vive due volte lo stesso giorno. Il suo tracciato, tuttavia, non è fissato da alcun trattato internazionale: la linea è soltanto il risultato delle scelte dei singoli paesi sul proprio fuso orario, e per questo devia dal meridiano per non dividere arcipelaghi e stati. Nel 2011 uno stato insulare del Pacifico che si trovava a est della linea ha deciso di passare sul lato occidentale, per allineare il proprio calendario a quello dei principali partner commerciali: nel paese, al 29 dicembre è seguito direttamente il 31.",
