   "passage": "Si chiama carsismo, dal nome dell'altopiano del Carso, l'insieme dei fenomeni prodotti dall'acqua nelle rocce solubili, soprattutto nei calcari. L'acqua piovana assorbe anidride carbonica dall'aria e dal suolo e diventa leggermente acida: in questo stato scioglie il carbonato di calcio e allarga a poco a poco le fratture della roccia. In superficie si formano così le doline, conche chiuse di forma per lo più circolare, e gli inghiottitoi, nei quali i corsi d'acqua scompaiono per proseguire sottoterra; per questo le regioni carsiche, anche se piovose, sono spesso povere di acque superficiali. Nelle grotte avviene il processo inverso: quando l'acqua che gocciola dalla volta libera anidride carbonica, il carbonato si deposita. Dalla volta pendono le stalattiti, dal pavimento crescono le stalagmiti, e le une e le altre possono saldarsi formando colonne. La crescita è molto lenta, spesso di pochi centimetri in mille anni, e si arresta del tutto quando l'acqua smette di filtrare, come accade nei periodi più secchi.",
