   "passage": "Quando un fiume separa due stati, il confine può essere tracciato in modi diversi. Per i fiumi navigabili la prassi internazionale adotta di solito il talweg, cioè la linea che unisce i punti più profondi dell'alveo, lungo la quale si concentra la navigazione: in questo modo entrambi gli stati conservano l'accesso al canale principale. Per i fiumi non navigabili si usa più spesso la linea mediana, equidistante dalle due rive. Entrambe le regole valgono soltanto in mancanza di un trattato che disponga diversamente. La questione si complica perché i fiumi cambiano corso. Se il letto si sposta lentamente, per l'erosione di una riva e il deposito di sedimenti sull'altra, il confine segue il fiume; se invece il corso d'acqua abbandona d'improvviso il vecchio alveo, per esempio durante una piena, il confine resta dov'era, e un tratto di territorio può trovarsi così sulla riva «sbagliata». In diversi casi i paesi interessati hanno poi negoziato uno scambio di terreni per riportare il confine sul fiume.",
