   "topic": "enclavi ed exclavi",
   "passage": "In geografia politica si chiama enclave un territorio interamente circondato da un solo altro stato, mentre exclave è una parte di uno stato separata dal resto del suo territorio. I due termini descrivono spesso lo stesso luogo da due punti di vista: un villaggio che appartiene a un paese ma è racchiuso tutto entro i confini del vicino è un'exclave per il primo e un'enclave per il secondo. Non sempre, però, le due condizioni si presentano insieme. Un territorio staccato dalla madrepatria che si affaccia sul mare, o che confina con più stati, è un'exclave ma non un'enclave. Al contrario, stati sovrani come San Marino e la Città del Vaticano sono enclavi ma non exclavi, perché costituiscono l'intero territorio del proprio stato. Uno dei casi più intricati si trova in una cittadina al confine tra Belgio e Paesi Bassi, dove una ventina di frazioni belghe sono circondate da territorio olandese e alcune di esse racchiudono a loro volta piccole porzioni dei Paesi Bassi.",
