   "passage": "Quando gruppi che non hanno una lingua in comune devono comunicare con regolarità, per esempio nei porti o nelle piantagioni, può nascere un pidgin: una lingua di contatto con un lessico ridotto e una grammatica essenziale, che nessuno parla come lingua materna. La maggior parte delle parole proviene di solito dalla lingua del gruppo dominante, detta lessificatrice, mentre la pronuncia e la costruzione delle frasi risentono delle lingue degli altri parlanti. Se un pidgin diventa la prima lingua dei bambini di una comunità, si trasforma in un creolo: il vocabolario si amplia e la grammatica acquista regole stabili, per esempio per esprimere il tempo dei verbi. Non tutti i pidgin, tuttavia, compiono questo passaggio: molti scompaiono quando cessano i contatti che li avevano fatti nascere. Secondo un'ipotesi molto discussa, i creoli di origini diverse si somigliano perché i bambini, ricostruendo la grammatica, attingerebbero a una capacità innata. Una lingua del Pacifico nata come pidgin nell'Ottocento è oggi lingua ufficiale di uno stato e la lingua materna di molti bambini cresciuti nelle sue città.",
