   "topic": "prestiti e calchi linguistici",
   "passage": "Quando una lingua accoglie elementi di un'altra, i linguisti distinguono il prestito dal calco. Nel prestito la parola straniera entra con la propria forma: talvolta resta quasi invariata, come «computer», talvolta si adatta ai suoni e alla morfologia della lingua che la riceve, come «bistecca», dall'inglese «beefsteak». Nel calco, invece, si imita il modello straniero con materiali propri. Il calco strutturale crea una parola nuova traducendo pezzo per pezzo un composto straniero: «grattacielo» riproduce l'inglese «skyscraper», «ferrovia» il tedesco «Eisenbahn». Il calco semantico non crea parole, ma attribuisce un significato nuovo a una parola già esistente: «realizzare», a lungo usato nel senso di «rendere reale», ha preso anche quello di «rendersi conto» sul modello dell'inglese «to realize». Poiché usano materiali della lingua stessa, i calchi passano spesso inosservati, mentre i prestiti non adattati si riconoscono subito; le polemiche sulla difesa della lingua si concentrano infatti su questi ultimi, anche se, secondo alcuni studiosi, sono i calchi a trasformare il lessico in modo più profondo.",
