   "passage": "I sistemi di scrittura si classificano secondo l'unità linguistica che ciascun segno rappresenta. Nei sistemi logografici un segno corrisponde a una parola o a una sua parte dotata di significato; nei sillabari a una sillaba; negli alfabeti a un singolo suono, consonante o vocale. Una categoria a parte è l'abjad, in cui si scrivono soltanto le consonanti, mentre le vocali, se compaiono, sono indicate da segni facoltativi: è il caso dell'arabo e dell'ebraico. L'alfabeto greco nacque proprio da un abjad, quello fenicio, quando alcuni segni per consonanti assenti in greco furono riutilizzati per le vocali. Le classificazioni descrivono però tendenze più che tipi puri: la maggior parte dei caratteri cinesi, l'esempio classico di scrittura logografica, contiene anche un elemento che suggerisce la pronuncia, e il giapponese combina caratteri di origine cinese con due sillabari. Il numero dei segni varia di conseguenza: poche decine in un alfabeto, migliaia in una scrittura logografica.",
