   "passage": "Il sonetto nacque nella prima metà del Duecento alla corte siciliana di Federico II, e la tradizione ne attribuisce l'invenzione a un notaio poeta, Giacomo da Lentini. Nella forma italiana è composto da quattordici endecasillabi, divisi in due quartine e due terzine; le quartine hanno rime alternate o incrociate, mentre per le terzine gli schemi sono più vari. Secondo un'ipotesi diffusa, ma non dimostrata, la forma deriverebbe da una singola strofa di canzone resa autonoma. Fu il Canzoniere di Petrarca, nel Trecento, a farne il metro lirico per eccellenza, e nel Cinquecento il modello petrarchesco si diffuse in tutta Europa. Passando ad altre lingue il sonetto cambiò: in Inghilterra si affermò una variante formata da tre quartine e da un distico finale a rima baciata, che conserva comunque il totale di quattordici versi. Anche il verso cambiò: al posto dell'endecasillabo i poeti inglesi usarono il pentametro giambico, e quelli francesi, spesso, l'alessandrino.",
