   "passage": "Nella crittografia simmetrica la stessa chiave serve a cifrare e a decifrare un messaggio, e le due parti devono quindi scambiarsela in modo sicuro prima di comunicare. La crittografia a chiave pubblica, sviluppata negli anni Settanta, risolve il problema assegnando a ogni utente due chiavi collegate: una pubblica, che può essere diffusa liberamente, e una privata, che resta segreta. Un messaggio cifrato con la chiave pubblica di una persona può essere decifrato soltanto con la sua chiave privata. Per la firma digitale il procedimento si rovescia: il mittente firma con la propria chiave privata e chiunque può verificare la firma con la chiave pubblica corrispondente. Poiché le operazioni asimmetriche sono lente, nella pratica servono di solito a scambiare una chiave simmetrica, che cifra poi il resto della comunicazione. La sicurezza di molti di questi sistemi si basa sulla difficoltà di scomporre in fattori numeri molto grandi; secondo diversi esperti, futuri computer quantistici potrebbero risolvere il problema in tempi brevi, e per questo sono già in corso di adozione nuovi algoritmi.",
