   "topic": "fibre ottiche monomodali e multimodali",
   "passage": "Una fibra ottica è formata da un nucleo di vetro sottilissimo rivestito da un mantello, anch'esso di vetro, con un indice di rifrazione leggermente inferiore. La luce che colpisce la superficie di separazione con un'inclinazione sufficiente viene riflessa interamente verso il nucleo e procede così lungo la fibra anche quando questa si curva, purché la curvatura non sia troppo stretta. Il vetro, tuttavia, assorbe una piccola parte della luce: nelle fibre migliori, alle lunghezze d'onda dell'infrarosso usate nelle telecomunicazioni, la potenza del segnale si dimezza ogni 15 chilometri circa, e sulle linee lunghe il segnale va amplificato a intervalli regolari. Nelle fibre multimodali, che hanno un nucleo più largo, la luce segue percorsi di lunghezza diversa e gli impulsi si allargano lungo il tragitto: per questo si usano soltanto su brevi distanze, per esempio all'interno di un edificio. Le fibre monomodali, con un nucleo di circa un centesimo di millimetro, evitano questo problema. Su una sola fibra, inoltre, possono viaggiare insieme decine di segnali, ciascuno su una lunghezza d'onda diversa.",
