   "topic": "superconduttività",
   "passage": "Nel 1911 si scoprì che il mercurio, raffreddato a circa 269 gradi sotto zero, perde del tutto la resistenza elettrica: è la superconduttività. Al di sotto della temperatura detta critica, una corrente avviata in un anello superconduttore può circolare per anni senza indebolirsi. Un superconduttore, inoltre, espelle il campo magnetico dal proprio interno, e per questo un piccolo magnete può restare sospeso sopra di esso; un campo troppo intenso, però, distrugge lo stato superconduttivo anche sotto la temperatura critica. Per decenni il fenomeno fu osservato solo vicino allo zero assoluto, usando come refrigerante il costoso elio liquido. Dal 1986 sono stati scoperti materiali ceramici superconduttori a temperature più alte, e alcuni lo sono anche sopra i 196 gradi sotto zero, la temperatura dell'azoto liquido, molto più economico. Eppure i magneti delle apparecchiature per la risonanza magnetica usano ancora quasi tutti leghe metalliche raffreddate con l'elio, più facili da lavorare in forma di filo. Negli ultimi anni sono stati annunciati più volte superconduttori a temperatura ambiente, ma nessuno è stato confermato.",
